-- 3. Post-import count checks
SELECT COUNT(*) AS matched_public_sources
FROM hainan_blue_carbon_core.t_data_source
WHERE source_code IN ('SRC_LIT_BAMEN_SOC_2022', 'SRC_LIT_FORESTS_HI_MANGROVE_RS_2023', 'SRC_LIT_FRONTIERS_HI_LULC_INVEST_2024', 'SRC_LIT_HI_GHG_2022', 'SRC_ALLO_KOMIYAMA_2005', 'SRC_BAAD_BIOMASS_AND_ALLOMETRY_DATABASE', 'SRC_GOV_HI_BLUE_CARBON_2023', 'SRC_IPCC_WETLANDS_SUPPLEMENT', 'SRC_TALLO_GLOBAL_TREE_ALLOMETRY_DATABASE');

SELECT COUNT(*) AS matched_public_regions
FROM hainan_blue_carbon_core.t_region
WHERE region_code IN ('REG_GLOBAL', 'REG_HI', 'REG_HI_DONGFANG', 'REG_HI_DONGZHAIGANG', 'REG_HI_GUANNAN', 'REG_HI_HUACHANGWAN', 'REG_HI_HUIWEN', 'REG_HI_ISLAND', 'REG_HI_MANIAOGANG', 'REG_HI_PUQIAN', 'REG_HI_XINYINGGANG', 'REG_HI_YANGPUGANG', 'REG_WENCHANG', 'REG_WENCHANG_BAMEN_BAY', 'REG_万宁市', 'REG_三亚市', 'REG_东方市', 'REG_临高县', 'REG_乐东县', 'REG_儋州市', 'REG_昌江县', 'REG_海口市', 'REG_澄迈县', 'REG_琼海市', 'REG_陵水县');

